// Detects AI models and harnesses/IDEs used to create a PR, matching the
// attribution convention "Created with <Model> in <Harness>".
//
// Only authoring evidence counts, so ordinary prose that happens to mention a
// tool name (for example "cursor" or "composer.json") never triggers it:
//   1. an explicit "Created with ..." line in the author-written part of the PR
//      body or in a commit message ("Reviewed with ..." lines describe a review,
//      not authorship, and are ignored), or
//   2. a Co-authored-by: trailer whose identity is a known AI agent, or
//   3. the older "created with the assistance of **<Model>**" wording that
//      CONTRIBUTING.md used to recommend.
// Code blocks (fenced or indented), HTML comments and bot-generated summaries
// are never read as evidence.
//
// When an agent is detected, the "ai-assisted" label is applied and, if the
// description lacks attribution, the line is placed at the end of the
// author-written part of the description, above any bot summaries.

export const AI_LABEL = 'ai-assisted';

// GitHub rejects issue and pull request bodies longer than this.
export const MAX_BODY_LENGTH = 65536;

// A whole line such as "Created with Claude Opus 5.5 in Claude Code, run from T3 Code."
// The model or the harness part may be absent ("Created with ChatGPT."), and
// names may contain dots or slashes ("Claude Sonnet 4.5", "WSL2/Ubuntu").
const WORD = String.raw`[\w-]+(?:[./][\w-]+)*`;
const NAME = `(${WORD}(?: ${WORD})*?)`;
export const ATTRIBUTION_LINE_PATTERN = new RegExp(
  String.raw`^\s*(Created|Reviewed) with ${NAME}(?: in ${NAME})?(?:,\s*run from ${NAME})?\s*\.?\s*$`,
  'i',
);

// Older format: "This PR was created with the assistance of **Claude Sonnet 4.6**".
const LEGACY_ATTRIBUTION_PATTERN = /\bcreated with the assistance of \*\*([^*<>\n]+?)\*\*/i;

const CO_AUTHOR_TRAILER_LINE = /^\s*Co-authored-by:\s*(.+?)\s*$/i;

// Lines that start a bot-generated section (Sourcery, CodeRabbit). The comment
// markers count only when they open a new comment outside a code block, and the
// heading only when it is prose.
const BOT_COMMENT_MARKERS = [
  /^<!-- Generated by sourcery-ai\[bot\]/,
  /^<!-- This is an auto-generated comment: release notes by coderabbit\.ai -->/,
];
const BOT_HEADING_MARKERS = [/^## Summary by Sourcery\s*$/];

const VERSION = String.raw`\d+(?:\.\d+)*`;
/** Upper-cases the first letter and lower-cases the rest. */
const titleCase = (s) => s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();

// Each family reports the model exactly as written (tier, version and variant
// included), so a version that is not listed anywhere is never rewritten into
// another one. `specific` is false for a bare family name such as "Claude",
// which is how agents name themselves and says nothing about the model used.
export const MODEL_FAMILIES = [
  {
    regex: new RegExp(
      String.raw`\bclaude(?:[- ](opus|sonnet|haiku))?(?:[- ](${VERSION}))?(?:[- ](opus|sonnet|haiku))?\b`,
      'i',
    ),
    format: ([, tierA, version, tierB]) => {
      const tier = tierA || tierB;
      return {
        name: ['Claude', tier && titleCase(tier), version].filter(Boolean).join(' '),
        specific: Boolean(tier || version),
      };
    },
  },
  {
    regex: new RegExp(
      String.raw`\bgpt-(${VERSION})(o?(?:-(?:mini|nano|turbo|preview|\d{4}-\d{2}-\d{2}|\d{4}))*)(?!\w|\.\d)`,
      'i',
    ),
    format: ([, version, variant = '']) => ({ name: `GPT-${version}${variant.toLowerCase()}`, specific: true }),
  },
  {
    regex: new RegExp(String.raw`\bgemini(?:[- ](${VERSION}))?(?:[- ](pro|flash|ultra|nano))?\b`, 'i'),
    format: ([, version, tier]) => ({
      name: ['Gemini', version, tier && titleCase(tier)].filter(Boolean).join(' '),
      specific: Boolean(version || tier),
    }),
  },
  {
    regex: new RegExp(String.raw`\bdeepseek(?:[- ]?([vr]${VERSION}))?\b`, 'i'),
    format: ([, version]) => ({
      name: version ? `DeepSeek-${version.toUpperCase()}` : 'DeepSeek',
      specific: Boolean(version),
    }),
  },
];

// A trailer counts as an agent only when its email is the agent's own address
// (never a whole company domain, which its employees share),
// or its display name (ignoring a parenthesised model) is exactly the tool's
// name. A person who merely shares a first name, such as "Aider Smith" or
// "Claude Martin", is not matched.
export const KNOWN_HARNESSES = [
  { name: 'Claude Code', names: ['claude code'], email: /^noreply@anthropic\.com$/i },
  { name: 'Cursor', names: ['cursor', 'cursor agent', 'cursoragent'], email: /^cursoragent@cursor\.com$/i },
  {
    name: 'GitHub Copilot',
    names: ['copilot', 'github copilot'],
    email: /^(?:\d+\+)?copilot@(?:users\.noreply\.)?github\.com$/i,
  },
  { name: 'ChatGPT', names: ['chatgpt'], email: /^chatgpt@openai\.com$/i },
  { name: 'Codex', names: ['codex', 'openai codex', 'codex agent'], email: /^codex@openai\.com$/i },
  { name: 'Antigravity', names: ['antigravity', 'google antigravity'] },
  { name: 'Windsurf', names: ['windsurf'] },
  { name: 'Aider', names: ['aider'], email: /^noreply@aider\.chat$/i },
  { name: 'T3 Code', names: ['t3 code', 't3code'] },
];

const FENCE_OPEN = /^\s*(?:(?:[-*+]|\d{1,9}[.)])\s+)*(`{3,}|~{3,})/;
const FENCE_CLOSE = /^\s*(`{3,}|~{3,})\s*$/;
const INDENTED = /^(?: {4}|\t)/;

/**
 * Blanks out inline code spans (`like this`) so delimiters inside them are not
 * mistaken for HTML comment markers. Keeps the string length unchanged.
 * @param {string} text
 * @returns {string}
 */
function maskInlineCode(text) {
  return text.replace(/(`+)(?:(?!\1).)+?\1/g, (span) => ' '.repeat(span.length));
}

/**
 * Classifies each line as 'prose', 'code' (fenced or indented code block,
 * including fences inside list items) or 'comment' (wholly or partly inside an
 * HTML comment). Also reports whether a comment was already open before each
 * line and what is still open at the end.
 * @param {string[]} lines
 * @returns {{types: string[], commentBefore: boolean[], openFence: string|null, openComment: boolean}}
 */
function classifyLines(lines) {
  let inComment = false;
  let fence = null;
  let inIndented = false;
  let prevBlank = true;
  let pendingBlanks = [];
  const types = [];
  const commentBefore = [];

  for (const line of lines) {
    commentBefore.push(inComment);
    const blank = !line.trim();
    let type;

    if (!inComment && fence) {
      const close = line.match(FENCE_CLOSE);
      if (close && close[1][0] === fence[0] && close[1].length >= fence.length) fence = null;
      type = 'code';
    } else if (!inComment && inIndented && !blank && INDENTED.test(line)) {
      // Blank lines between two lines of the same indented block are code too.
      for (const i of pendingBlanks) types[i] = 'code';
      type = 'code';
    } else if (!inComment && FENCE_OPEN.test(line)) {
      fence = line.match(FENCE_OPEN)[1];
      inIndented = false;
      type = 'code';
    } else if (!inComment && !blank && INDENTED.test(line) && prevBlank) {
      inIndented = true;
      type = 'code';
    } else {
      if (!blank) inIndented = false;
      let touched = inComment;
      let rest = line;
      while (rest) {
        const token = inComment ? '-->' : '<!--';
        const at = (inComment ? rest : maskInlineCode(rest)).indexOf(token);
        if (at === -1) break;
        touched = true;
        inComment = !inComment;
        rest = rest.slice(at + token.length);
      }
      type = touched ? 'comment' : 'prose';
    }

    if (blank && inIndented && type === 'prose') pendingBlanks.push(types.length);
    else pendingBlanks = [];
    types.push(type);
    prevBlank = blank;
  }
  return { types, commentBefore, openFence: fence, openComment: inComment };
}

/** Splits text into lines, treating CRLF and LF alike. */
function splitLines(text) {
  return (text || '').replace(/\r\n/g, '\n').split('\n');
}

/** Returns only the prose lines of the text (no code blocks or HTML comments). */
function proseLines(text) {
  const lines = splitLines(text);
  const { types } = classifyLines(lines);
  return lines.filter((_, i) => types[i] === 'prose');
}

/**
 * Splits a PR body into the author-written part and the bot-generated part.
 */
export function splitAuthorSection(body) {
  const lines = splitLines(body);
  const { types, commentBefore } = classifyLines(lines);
  const cut = lines.findIndex((line, i) => {
    if (types[i] === 'code' || commentBefore[i]) return false;
    if (types[i] === 'prose') return BOT_HEADING_MARKERS.some((m) => m.test(line));
    return BOT_COMMENT_MARKERS.some((m) => m.test(line));
  });
  if (cut === -1) return [lines.join('\n'), ''];
  return [lines.slice(0, cut).join('\n'), lines.slice(cut).join('\n')];
}

/**
 * Parses one line as a "Created with ..." attribution; returns null for anything else, including "Reviewed with ..." lines.
 */
function parseAttributionLine(line) {
  const match = line.match(ATTRIBUTION_LINE_PATTERN);
  if (!match || match[1].toLowerCase() !== 'created') return null;
  return {
    raw: match[0].trim(),
    action: 'Created',
    model: match[2].trim(),
    harness: match[3]?.trim() || null,
    environment: match[4]?.trim() || null,
  };
}

/**
 * Returns the last "Created with ..." prose line in the text, ignoring code
 * blocks, HTML comments and "Reviewed with ..." lines.
 */
export function parseExistingAttribution(text) {
  const lines = proseLines(text);
  for (let i = lines.length - 1; i >= 0; i -= 1) {
    const parsed = parseAttributionLine(lines[i]);
    if (parsed) return parsed;
  }
  return null;
}

/**
 * Returns the model named in the older "created with the assistance of **<Model>**" wording, or null.
 */
function parseLegacyAttribution(text) {
  for (const line of proseLines(text)) {
    const match = line.match(LEGACY_ATTRIBUTION_PATTERN);
    if (match) return match[1].trim();
  }
  return null;
}

/**
 * Finds the first model name in the text, reported as written. With `requireSpecific`, a bare family name such as "Claude" is skipped.
 */
export function detectModel(text, { requireSpecific = false } = {}) {
  for (const family of MODEL_FAMILIES) {
    const match = (text || '').match(family.regex);
    if (!match) continue;
    const { name, specific } = family.format(match);
    if (requireSpecific && !specific) continue;
    return name;
  }
  return null;
}

/** Escapes regular-expression special characters in a string. */
const escapeRegExp = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

/** Identifies the agent (harness) and model named by one Co-authored-by: trailer value. */
function detectFromTrailer(trailer) {
  const emailMatch = trailer.match(/<([^>]*)>/);
  const email = emailMatch ? emailMatch[1].trim() : '';
  const displayName = trailer.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
  const bareName = displayName.replace(/\([^)]*\)/g, ' ').replace(/\s+/g, ' ').trim().toLowerCase();

  const harness =
    KNOWN_HARNESSES.find((h) => (h.email && h.email.test(email)) || h.names.includes(bareName))?.name || null;
  if (!harness) return { harness: null, model: null };

  // Only the display name can carry model information; the email is identity.
  // Drop tool names first so "Claude Code" is not read as a model, and accept
  // only a specific model, not a bare agent name such as "Claude".
  let modelText = displayName;
  for (const h of KNOWN_HARNESSES) {
    for (const name of h.names) {
      modelText = modelText.replace(new RegExp(`\\b${escapeRegExp(name)}\\b`, 'gi'), ' ');
    }
  }
  return { harness, model: detectModel(modelText, { requireSpecific: true }) };
}

/**
 * Detects agent details from authoring evidence only.
 * `body` is the PR description; `commitMessages` is a list of commit messages.
 */
export function detectAgentDetails({ body = '', commitMessages = [] } = {}) {
  const [authorBody] = splitAuthorSection(body);

  for (const text of [authorBody, ...commitMessages]) {
    const existing = parseExistingAttribution(text);
    if (existing) {
      return {
        model: existing.model,
        harness: existing.harness,
        environment: existing.environment,
        explicit: true,
      };
    }
  }

  // Model and harness always come from the same trailer, so two trailers are
  // never combined into a pairing neither of them states. A trailer that names
  // both wins over one that names only the harness.
  let best = null;
  for (const message of commitMessages) {
    for (const line of proseLines(message)) {
      const match = line.match(CO_AUTHOR_TRAILER_LINE);
      if (!match) continue;
      const found = detectFromTrailer(match[1]);
      if (!found.harness) continue;
      if (!best || (!best.model && found.model)) best = found;
    }
  }
  if (best?.model) return { model: best.model, harness: best.harness, environment: null, explicit: false };

  // A model disclosed in the older wording beats a trailer that names no model.
  for (const text of [authorBody, ...commitMessages]) {
    const legacyModel = parseLegacyAttribution(text);
    if (legacyModel) return { model: legacyModel, harness: null, environment: null, explicit: true };
  }

  if (best) return { model: null, harness: best.harness, environment: null, explicit: false };
  return null;
}

/**
 * Formats "<Action> with <Model> in <Harness>, run from <Environment>."
 * A missing model or harness is left out instead of being invented.
 */
export function formatAttributionLine({ action = 'Created', model, harness, environment }) {
  let line = `${action} with ${model || harness}`;
  if (model && harness) line += ` in ${harness}`;
  if (environment) line += `, run from ${environment}`;
  return `${line}.`;
}

/**
 * True when the attribution line is the only "Created with" prose line in the
 * author section and nothing (prose or code) follows it.
 */
function endsWithOnlyAttribution(lines, classified, attributionLine) {
  const { types, openFence, openComment } = classified;
  if (openFence || openComment) return false;
  const attributionIndexes = lines.flatMap((line, i) =>
    types[i] === 'prose' && parseAttributionLine(line) ? [i] : [],
  );
  if (attributionIndexes.length !== 1) return false;
  let lastContent = -1;
  lines.forEach((line, i) => {
    if (line.trim() && types[i] !== 'comment') lastContent = i;
  });
  return lastContent === attributionIndexes[0] && lines[lastContent].trim() === attributionLine;
}

/**
 * Places the attribution line at the end of the author-written part of the body,
 * above any bot-generated summaries, and removes stray "Created with" prose lines
 * elsewhere in that part. Code blocks and HTML comments are kept exactly as they
 * are; a code block or comment left open at the end is closed first so the line
 * stays visible. Returns the body unchanged when it already ends with the line.
 */
export function appendAttributionToBody(body, attributionLine) {
  const [authorSection, botSection] = splitAuthorSection(body);
  const lines = splitLines(authorSection);
  const classified = classifyLines(lines);
  if (endsWithOnlyAttribution(lines, classified, attributionLine)) {
    return body || '';
  }

  const { types, openFence, openComment } = classified;
  const out = [];
  const outTypes = [];
  lines.forEach((line, i) => {
    const type = types[i];
    if (type === 'prose' && parseAttributionLine(line)) return;
    // Collapse runs of blank prose lines; blank lines in code are kept.
    if (type === 'prose' && !line.trim() && out.length && !out[out.length - 1].trim() && outTypes[outTypes.length - 1] === 'prose') {
      return;
    }
    out.push(line);
    outTypes.push(type);
  });
  while (out.length && !out[out.length - 1].trim() && outTypes[outTypes.length - 1] === 'prose') {
    out.pop();
    outTypes.pop();
  }
  if (openFence) out.push(openFence);
  if (openComment) out.push('-->');

  const kept = out.join('\n');
  const updatedAuthor = kept.trim() ? `${kept}\n\n${attributionLine}\n` : `${attributionLine}\n`;
  return botSection ? `${updatedAuthor}\n${botSection}` : updatedAuthor;
}

/** True for errors worth retrying: network failures, rate limits and server errors. */
function isTransient(error) {
  return !error.status || error.status === 429 || error.status >= 500;
}

/** Raised when the PR changed under a running job, so the newer run should handle it. */
class StaleRunError extends Error {}

/** Runs `fn`, retrying transient failures with a growing delay. */
export async function withRetry(fn, { attempts = 3, delayMs = 1000, core } = {}) {
  for (let attempt = 1; ; attempt += 1) {
    try {
      return await fn();
    } catch (error) {
      if (error instanceof StaleRunError || attempt >= attempts || !isTransient(error)) throw error;
      core?.warning(`Transient error (${error.status || error.message}); retrying (${attempt}/${attempts - 1}).`);
      await new Promise((resolve) => setTimeout(resolve, delayMs * attempt));
    }
  }
}

/**
 * Lists every commit message on the PR. The pull request commits endpoint stops
 * at 250 commits, so larger PRs fall back to the compare API, which pages
 * through all of them. A result that is still short is reported, not hidden.
 * Each read is retried on transient errors.
 */
async function listAllCommitMessages({ github, owner, repo, pr, core, retry }) {
  const commits = await withRetry(
    () =>
      github.paginate(github.rest.pulls.listCommits, {
        owner,
        repo,
        pull_number: pr.number,
        per_page: 100,
      }),
    retry,
  );
  let messages = commits.map((c) => c.commit?.message).filter(Boolean);

  const expected = pr.commits ?? messages.length;
  if (messages.length < expected) {
    const all = [];
    for (let page = 1; ; page += 1) {
      const { data } = await withRetry(
        () =>
          github.rest.repos.compareCommitsWithBasehead({
            owner,
            repo,
            basehead: `${pr.base.sha}...${pr.head.sha}`,
            per_page: 100,
            page,
          }),
        retry,
      );
      const pageCommits = data.commits || [];
      all.push(...pageCommits);
      if (pageCommits.length < 100) break;
    }
    if (all.length > messages.length) {
      messages = all.map((c) => c.commit?.message).filter(Boolean);
    }
    if (messages.length < expected) {
      core.warning(
        `#${pr.number}: read ${messages.length} of ${expected} commits; ` +
          'trailers in the missing commits were not checked.',
      );
    }
  }
  return messages;
}

/** Creates the ai-assisted label if needed and adds it to the PR. */
async function ensureLabel({ github, owner, repo, prNumber, labels, core }) {
  if (labels.includes(AI_LABEL)) return;

  try {
    await github.rest.issues.getLabel({ owner, repo, name: AI_LABEL });
  } catch (error) {
    if (error.status !== 404) throw error;
    try {
      await github.rest.issues.createLabel({
        owner,
        repo,
        name: AI_LABEL,
        color: '7B61FF',
        description: 'PR created or assisted with an AI coding agent',
      });
      core.info(`Created label "${AI_LABEL}".`);
    } catch (createError) {
      if (createError.status !== 422) throw createError;
    }
  }

  await github.rest.issues.addLabels({
    owner,
    repo,
    issue_number: prNumber,
    labels: [AI_LABEL],
  });
  core.info(`#${prNumber}: Added "${AI_LABEL}" label.`);
}

/**
 * Reads the PR and stops the run if its head moved since this run started, so a
 * run that began before a force-push never writes results based on removed commits.
 */
async function readCurrentPr({ github, owner, repo, prNumber, headSha }) {
  const { data } = await github.rest.pulls.get({ owner, repo, pull_number: prNumber });
  if (data.state !== 'open' || (headSha && data.head?.sha !== headSha)) {
    throw new StaleRunError(`#${prNumber} changed since this run started; leaving it to the newer run.`);
  }
  return data;
}

/** Adds or moves the attribution line in the PR description without overwriting newer edits. */
async function ensureAttribution({ github, owner, repo, prNumber, headSha, commitMessages, core }) {
  // GitHub has no conditional update for PR bodies. Read, build the new body,
  // then read again right before writing and start over if the body changed,
  // so an author's edit can only be lost inside a single request's window.
  for (let attempt = 1; attempt <= 3; attempt += 1) {
    const latest = await readCurrentPr({ github, owner, repo, prNumber, headSha });
    const latestBody = latest.body || '';

    // Detect again from the latest body: if the author removed the only
    // evidence, nothing is written back.
    const detected = detectAgentDetails({ body: latestBody, commitMessages });
    if (!detected) {
      core.info(`#${prNumber}: Attribution evidence is gone from the latest description; not adding it.`);
      return;
    }
    const [authorBody] = splitAuthorSection(latestBody);
    const lineToPlace = parseExistingAttribution(authorBody)?.raw || formatAttributionLine(detected);
    const updatedBody = appendAttributionToBody(latestBody, lineToPlace);

    if (updatedBody === latestBody) {
      core.info(`#${prNumber}: PR description already ends with attribution.`);
      return;
    }
    if (updatedBody.length > MAX_BODY_LENGTH) {
      core.warning(`#${prNumber}: PR description is too long to add attribution; skipped.`);
      return;
    }

    const check = await readCurrentPr({ github, owner, repo, prNumber, headSha });
    if ((check.body || '') !== latestBody) {
      core.info(`#${prNumber}: PR description changed while preparing the update; re-reading.`);
      continue;
    }

    await github.rest.pulls.update({ owner, repo, pull_number: prNumber, body: updatedBody });
    core.info(`#${prNumber}: Placed attribution at the end of the PR description.`);
    return;
  }
  core.warning(`#${prNumber}: PR description kept changing; attribution not added this run.`);
}

/**
 * Entry point for the workflow: detects AI authoring evidence on the PR, then applies the label and the attribution line.
 */
export async function runAgentAttribution({ github, context, core, retryDelayMs = 1000 }) {
  const { owner, repo } = context.repo;
  const prNumber = context.payload.pull_request?.number;

  if (!prNumber) {
    core.info('No pull request found in context, nothing to do.');
    return;
  }

  const retry = { core, delayMs: retryDelayMs };
  const { data: pr } = await withRetry(() => github.rest.pulls.get({ owner, repo, pull_number: prNumber }), retry);

  if (pr.state !== 'open') {
    core.info(`#${prNumber} is ${pr.state}, skipping.`);
    return;
  }

  const headSha = pr.head?.sha;
  const commitMessages = await listAllCommitMessages({
    github,
    owner,
    repo,
    pr: { ...pr, number: prNumber },
    core,
    retry,
  });

  try {
    // Re-read so detection uses the latest body, and stop if a force-push
    // moved the head while the commits were being listed.
    const current = await withRetry(() => readCurrentPr({ github, owner, repo, prNumber, headSha }), retry);
    const detected = detectAgentDetails({ body: current.body || '', commitMessages });
    if (!detected) {
      core.info(`#${prNumber}: No AI authoring evidence found.`);
      return;
    }
    core.info(`#${prNumber}: Detected AI attribution -> "${formatAttributionLine(detected)}"`);

    // The label goes first and on its own, so a skipped body update never leaves
    // the PR unlabelled. Transient failures are retried; if the body update still
    // fails, the next run (edit, push or manual dispatch) adds the missing line.
    const labels = (current.labels || []).map((l) => l.name);
    await withRetry(() => ensureLabel({ github, owner, repo, prNumber, labels, core }), retry);
    await withRetry(
      () => ensureAttribution({ github, owner, repo, prNumber, headSha, commitMessages, core }),
      retry,
    );
  } catch (error) {
    if (error instanceof StaleRunError) {
      core.info(error.message);
      return;
    }
    throw error;
  }
}
